+func sanitizeText(value string) string {
+	value = strings.ReplaceAll(value, "\r\n", "\n")
+	value = strings.ReplaceAll(value, "\r", "\n")
+	value = strings.ReplaceAll(value, "\x00", "")
+	value = secretAssignmentPattern.ReplaceAllString(value, "${1}=[REDACTED]")
+	value = secretValuePattern.ReplaceAllString(value, "[REDACTED_SECRET]")
+
+	lines := strings.Split(value, "\n")
+	kept := make([]string, 0, len(lines))
+	redacted := false
+	for _, line := range lines {
+		trimmed := strings.TrimSpace(line)
+		if trimmed == "" {
+			continue
+		}
+		if unsafePromptLine(trimmed) {
+			redacted = true
+			continue
+		}
+		kept = append(kept, trimmed)
+	}
+	if redacted {
+		kept = append(kept, "[REDACTED UNSAFE CONTENT]")
+	}
+	result := strings.TrimSpace(whitespacePattern.ReplaceAllString(strings.Join(kept, " "), " "))
+	if result == "" && redacted {
+		result = "[REDACTED UNSAFE CONTENT]"
+	}
+	return truncateRunes(result, maxPromptTextRunes)
+}
+
+func sanitizePath(value string) string {
+	value = strings.ReplaceAll(value, "\r\n", "\n")
+	value = strings.ReplaceAll(value, "\r", "\n")
+	value = strings.ReplaceAll(value, "\x00", "")
+	value = strings.TrimSpace(value)
+	if i := strings.IndexByte(value, '\n'); i >= 0 {
+		value = strings.TrimSpace(value[:i])
+	}
+	if value == "" {
+		return ""
+	}
+	if unsafePromptLine(value) {
+		return "[REDACTED_PATH]"
+	}
+	return truncateRunes(value, maxPromptPathRunes)
