	t.Parallel()
	base := `{"summary":"ok","requirements":[{"id":"R1","requirement":"behavior","status":"IMPLEMENTED","confidence":0.9,"evidence":[{"type":"code","explanation":"exists"},{"type":"test","explanation":"verified","result":"passed"}],"recommendation":""}]}`
