		"empty evidence":           strings.Replace(base, evidence, "[]", 1),
		"unknown evidence type":    strings.Replace(base, "\"type\":\"code\"", "\"type\":\"database\"", 1),
		"misspelled evidence type": strings.Replace(base, "\"type\":\"code\"", "\"type\":\"git-diff\"", 1),
